SELECT CAST(created_at_utc + INTERVAL 6 HOUR AS DATE) AS dd, SUM(CASE WHEN status = 'captured' THEN 1 ELSE 0 END) * 1.0 / SUM(CASE WHEN status IN ('captured', 'failed') THEN 1 ELSE 0 END) AS success FROM payments WHERE method = 'bkash' AND created_at_utc >= TIMESTAMP '2025-08-01 00:00:00' - INTERVAL 6 HOUR AND created_at_utc < TIMESTAMP '2025-08-31 00:00:00' + INTERVAL 18 HOUR GROUP BY dd ORDER BY success LIMIT 3
